CREATE MATERIALIZED VIEW public.library_signal_series_mat AS SELECT * FROM public.library_signal_series;
CREATE UNIQUE INDEX library_signal_series_mat_key ON public.library_signal_series_mat(bucket,sector);
CREATE MATERIALIZED VIEW public.library_css_series_mat AS SELECT * FROM public.library_css_series;
CREATE UNIQUE INDEX library_css_series_mat_key ON public.library_css_series_mat(bucket,sector,feature);
CREATE MATERIALIZED VIEW public.library_font_series_mat AS SELECT * FROM public.library_font_series;
CREATE UNIQUE INDEX library_font_series_mat_key ON public.library_font_series_mat(bucket,role,family);
CREATE MATERIALIZED VIEW public.library_tag_series_mat AS SELECT * FROM public.library_tag_series;
CREATE UNIQUE INDEX library_tag_series_mat_key ON public.library_tag_series_mat(bucket,sector,dimension,value);
REVOKE ALL ON public.library_signal_series_mat,public.library_css_series_mat,public.library_font_series_mat,public.library_tag_series_mat FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.library_signal_series_mat,public.library_css_series_mat,public.library_font_series_mat,public.library_tag_series_mat TO service_role;
CREATE VIEW public.library_signal_history AS SELECT * FROM public.library_signal_series_mat;
CREATE VIEW public.library_css_history AS SELECT * FROM public.library_css_series_mat;
CREATE VIEW public.library_font_history AS SELECT * FROM public.library_font_series_mat;
CREATE VIEW public.library_tag_history AS SELECT * FROM public.library_tag_series_mat;
GRANT SELECT ON public.library_signal_history,public.library_css_history,public.library_font_history,public.library_tag_history TO anon,authenticated,service_role;
CREATE TABLE public.library_history_control(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),dirty boolean NOT NULL DEFAULT false);
GRANT ALL ON public.library_history_control TO service_role;
ALTER TABLE public.library_history_control ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.library_history_dirty() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.library_history_control(id,dirty) VALUES(1,true) ON CONFLICT(id) DO UPDATE SET dirty=true; RETURN NULL; END; $$;
CREATE TRIGGER library_history_snapshot_dirty AFTER INSERT ON public.library_snapshots FOR EACH STATEMENT EXECUTE FUNCTION public.library_history_dirty();
CREATE TRIGGER library_history_tag_dirty AFTER INSERT OR UPDATE OR DELETE ON public.library_tags FOR EACH STATEMENT EXECUTE FUNCTION public.library_history_dirty();
CREATE FUNCTION public.refresh_library_history() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('library_history_refresh',0));
 PERFORM 1 FROM public.library_history_control WHERE id=1 AND dirty=true FOR UPDATE;
 IF NOT FOUND THEN RETURN; END IF;
 REFRESH MATERIALIZED VIEW public.library_signal_series_mat;
 REFRESH MATERIALIZED VIEW public.library_css_series_mat;
 REFRESH MATERIALIZED VIEW public.library_font_series_mat;
 REFRESH MATERIALIZED VIEW public.library_tag_series_mat;
 UPDATE public.library_history_control SET dirty=false WHERE id=1;
 END; $$;
REVOKE ALL ON FUNCTION public.refresh_library_history(),public.library_history_dirty() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_library_history() TO service_role;